173	</head>
174	<body>
175	  <main>
176	    <h1 class="visually-hidden">Animated Circle</h1>
177	    <button type="button" class="no-transition" aria-label="Change circle color" aria-describedby="status hint">
178	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
179	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
180	      </svg>
181	    </button>
182	    <p class="status" id="status" role="status" aria-atomic="true">Blue</p>
183	    <p class="hint" id="hint"><span class="verb">Click</span> to change color (or press <kbd>Space</kbd> or <kbd>Enter</kbd>; hold <kbd>Shift</kbd> to go back; arrow keys also work; <kbd>Home</kbd>/<kbd>End</kbd> jump to first/last)</p>
184	  </main>
185	  <script>
186	    const button = document.querySelector('button');
187	    const status = document.querySelector('.status');
188	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
189	    const storageKey = 'circle-color';
190	
191	    function loadColor() {
192	      try {
193	        return localStorage.getItem(storageKey);
194	      } catch {
195	        return null;
196	      }
197	    }
198	
199	    function saveColor(color) {
200	      try {
201	        localStorage.setItem(storageKey, color);
202	      } catch {}
203	    }
204	
205	    const savedColor = loadColor();
206	    let index = colors.includes(savedColor) ? colors.indexOf(savedColor) : 0;
207	
208	    function applyColor() {
209	      const color = colors[index];
210	      if (color === 'blue') {
211	        delete button.dataset.color;
212	      } else {
213	        button.dataset.color = color;
214	      }
215	      status.textContent = color[0].toUpperCase() + color.slice(1);
216	    }
217	
218	    function changeColor(step) {
219	      index = (index + step + colors.length) % colors.length;
220	      applyColor();
221	      saveColor(colors[index]);
222	
223	      button.classList.remove('color-changed');
224	      void button.offsetWidth;
225	      button.classList.add('color-changed');
226	    }
227	
228	    applyColor();
229	    requestAnimationFrame(() => {
230	      requestAnimationFrame(() => button.classList.remove('no-transition'));
231	    });
232	
233	    const hoverQuery = matchMedia('(hover: none)');
234	    const verbSpan = document.querySelector('.hint .verb');
235	    function updateVerb() {
236	      verbSpan.textContent = hoverQuery.matches ? 'Tap' : 'Click';
237	    }
238	    updateVerb();
239	    hoverQuery.addEventListener('change', updateVerb);
240	
241	    // Keyboard-synthesized clicks don't reliably carry shiftKey across
242	    // browsers, so handle keys here and suppress the native activation.
243	    const keySteps = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
244	    button.addEventListener('keydown', (event) => {
245	      if (event.altKey || event.ctrlKey || event.metaKey) return;
246	      if (event.key === 'Enter' || event.key === ' ') {
247	        event.preventDefault();
248	        if (!event.repeat) changeColor(event.shiftKey ? -1 : 1);
249	      } else if (event.key in keySteps) {
250	        event.preventDefault();
251	        changeColor(keySteps[event.key]);
252	      } else if (event.key === 'Home') {
253	        event.preventDefault();
254	        changeColor(-index);
255	      } else if (event.key === 'End') {
256	        event.preventDefault();
257	        changeColor(colors.length - 1 - index);
258	      }
259	    });
260	    button.addEventListener('click', (event) => {
261	      changeColor(event.shiftKey ? -1 : 1);
262	    });
263	    button.addEventListener('animationend', () => {
264	      button.classList.remove('color-changed');
265	    });
266	    addEventListener('storage', (event) => {
267	      if (event.key === storageKey && colors.includes(event.newValue)) {
268	        index = colors.indexOf(event.newValue);
269	        applyColor();
270	      }
271	    });
272	  </script>
273	</body>
274	</html>
